# The app's older icon names (ui/icons.py glyphs), so every existing call site draws Lucide too.
ALIASES = {
    "cross": "x", "close": "x", "warn": "triangle-alert", "unlock": "lock-open", "next": "skip-forward",
    "previous": "skip-back", "people": "users", "chat": "message-square-more", "connect": "plug",
    "disconnect": "unplug", "clear": "eraser", "popout": "external-link", "broadcast": "radio",
    "zap": "zap", "chart": "chart-column", "controller": "gamepad", "gear": "settings", "home": "house",
    "bell": "bell", "puzzle": "puzzle", "clock": "clock", "star": "star",
}


def name_of(name: str) -> str:
    return ALIASES.get(name, name)


def svg(name: str, color: str, stroke: float = 2.0) -> str:
    body = ICONS[name_of(name)]
    return (f'<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" '
            f'stroke="{color}" stroke-width="{stroke}" stroke-linecap="round" stroke-linejoin="round" '
            f'color="{color}">{body}</svg>')


@lru_cache(maxsize=512)
def pixmap(name: str, color: str, size: int = 16, stroke: float = 2.0) -> QPixmap:
    image = QPixmap(size * SCALE, size * SCALE)
    image.fill(Qt.GlobalColor.transparent)
    renderer = QSvgRenderer(QByteArray(svg(name, color, stroke).replace("currentColor", color).encode()))
    painter = QPainter(image)
    painter.setRenderHint(QPainter.RenderHint.Antialiasing)
    renderer.render(painter, QRectF(0, 0, size * SCALE, size * SCALE))
    painter.end()
    image.setDevicePixelRatio(SCALE)
    return image


def icon(name: str, color: str, size: int = 16) -> QIcon:
    return QIcon(pixmap(name, color, size))
